{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual cap","requirement":"Landlords may not increase residential rent by more than the lower of 3% per year or 80% of the 12-month CPI change, and no increase is allowed when CPI is negative. Owners may petition for relief.","key_value":"lower of 3% per year or 80% of 12-month CPI change; no increase if CPI negative","coverage_conditions":"Residential rental units in Santa Ana, but not buildings constructed after February 1, 1995, or mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Mobile home spaces offered after Jan 1, 1990 excluded; owner petition for relief available."},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days of tenancy, an owner may not terminate without just cause stated in written notice. For no-fault just cause, the owner must provide 3 months' relocation assistance or waive the final 3 months' rent.","key_value":"3 months' relocation assistance or final 3 months' rent waiver","coverage_conditions":"Residential tenancies after 30 days. Excludes housing produced in the last 15 years, deed-restricted affordable housing, hotels, hospitals and care facilities, dormitories, and shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Covers tenancies after 30 days; exempts housing produced in last 15 years and listed property types."},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; other shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
